package com.example.demo.config;

import org.springframework.boot.context.properties.ConfigurationProperties;

import javax.annotation.PostConstruct;

/** Feature flags bound from application properties. Uses javax.annotation.PostConstruct. */
@ConfigurationProperties(prefix = "app.features")
public class FeatureProperties {

    private boolean newPricing = false;
    private boolean auditLog = true;

    @PostConstruct
    public void validate() {
        // no-op validation hook
    }

    public boolean isNewPricing() {
        return newPricing;
    }

    public void setNewPricing(boolean newPricing) {
        this.newPricing = newPricing;
    }

    public boolean isAuditLog() {
        return auditLog;
    }

    public void setAuditLog(boolean auditLog) {
        this.auditLog = auditLog;
    }
}
package com.example.demo.config;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.web.filter.CorsFilter;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.UrlBasedCorsConfigurationSource;

import javax.servlet.Filter;
import org.springframework.boot.web.servlet.FilterRegistrationBean;

/**
 * Web config. Uses javax.servlet.* (removed in Spring 6 / Boot 3) and should
 * become jakarta.servlet.* on migration.
 */
@Configuration
public class WebConfig {

    @Bean
    public CorsFilter corsFilter() {
        UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
        CorsConfiguration config = new CorsConfiguration();
        config.addAllowedOrigin("*");
        config.addAllowedMethod("*");
        config.addAllowedHeader("*");
        source.registerCorsConfiguration("/api/**", config);
        return new CorsFilter(source);
    }

    @Bean
    public FilterRegistrationBean<Filter> loggingFilter() {
        FilterRegistrationBean<Filter> registration = new FilterRegistrationBean<>();
        registration.addUrlPatterns("/api/*");
        registration.setName("loggingFilter");
        return registration;
    }
}
package com.example.demo;

import com.example.demo.entity.Customer;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

/** JUnit 4 test — must be migrated to JUnit 5 (Jupiter) on the Boot 3.x upgrade. */
public class CustomerTest {

    @Test
    public void constructorSetsFields() {
        Customer c = new Customer("Ada Lovelace", "ada@example.com", "GOLD");
        assertEquals("Ada Lovelace", c.getFullName());
        assertEquals("ada@example.com", c.getEmail());
        assertEquals("GOLD", c.getTier());
        assertNotNull("createdAt should be set", c.getCreatedAt());
    }

    @Test
    public void settersWork() {
        Customer c = new Customer();
        c.setFullName("Grace Hopper");
        c.setEmail("grace@example.com");
        c.setTier("SILVER");
        assertEquals("Grace Hopper", c.getFullName());
        assertEquals("SILVER", c.getTier());
    }
}
package com.example.demo.service;

import com.example.demo.repo.CustomerRepository;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

import java.util.List;
import java.util.Optional;

/** JUnit 4 + Mockito test for CustomerService. Migrate to JUnit 5 + MockitoExtension. */
public class CustomerServiceTest {

    private CustomerRepository repository;
    private CustomerService service;

    @Before
    public void setUp() {
        repository = Mockito.mock(CustomerRepository.class);
        service = new CustomerService(repository);
    }

    @Test
    public void byEmailDelegatesToRepository() {
        when(repository.findByEmail("x@example.com"))
                .thenReturn(Optional.of(new com.example.demo.entity.Customer("X", "x@example.com", "GOLD")));

        Optional<com.example.demo.entity.Customer> result = service.byEmail("x@example.com");

        assertTrue(result.isPresent());
        assertEquals("X", result.get().getFullName());
    }

    @Test
    public void allReturnsRepositoryList() {
        when(repository.findAll()).thenReturn(List.of());
        assertEquals(0, service.all().size());
    }
}
